<?php if (!$selected): ?><label>Selecciona un archivo<input type="file" name="file" required></label><p class="nx-note">Hasta 20 MB, sujeto a la configuración PHP del servidor. Se guarda fuera de public y se calcula su checksum SHA-256. El contenido no se ejecuta.</p><label>Versión de un recurso existente<select name="parent_id"><option value="0">Crear un recurso nuevo</option><?php foreach ($resources as $resource): ?><option value="<?= (int)$resource['id'] ?>"><?= $e($resource['title'].' · v'.$resource['version_label']) ?></option><?php endforeach ?></select></label><label><input type="checkbox" name="override_permissions" value="1"> En una nueva versión, aplicar los permisos de este formulario en lugar de heredarlos.</label><?php endif ?>
<label>Quién puede descargar<select name="access_mode"><?php foreach (['public_link'=>'Quien tenga un enlace válido','authenticated'=>'Usuarios con sesión iniciada','specific_user'=>'Solo la cuenta asignada'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($selected['access_mode']??'public_link')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label>Cuenta asignada (si corresponde)<select name="assigned_user"><option value="0">Sin asignación</option><?php foreach ($users as $user): ?><option value="<?= (int)$user['id'] ?>" <?= (int)($selected['assigned_user']??0)===(int)$user['id']?'selected':'' ?>><?= $e($user['username']) ?></option><?php endforeach ?></select></label><button class="nx-btn primary"><?= $selected?'Guardar metadatos y permisos':'Guardar archivo privado' ?></button></form></section>
<section class="nx-panel"><div class="nx-panel-head"><h2>Cómo funciona la entrega</h2></div><div class="nx-panel-body nx-stack"><div class="nx-check"><div><strong>Sube y organiza</strong><p>Las versiones tienen archivos y checksums independientes. Una versión nueva no sustituye silenciosamente los bytes de una anterior.</p></div></div><div class="nx-check"><div><strong>Define permisos</strong><p>El recurso puede exigir sesión o una cuenta concreta. Esas condiciones se comprueban aunque alguien copie el enlace.</p></div></div><div class="nx-check"><div><strong>Crea un enlace controlado</strong><p>Elige su vigencia, límite de accesos y destinatario opcional. La revocación impide nuevas entregas.</p></div></div><div class="nx-check"><div><strong>Revisa el registro</strong><p>Se cuentan autorizaciones de entrega; el servidor no puede confirmar que el navegador haya recibido y guardado todos los bytes.</p></div></div><p class="nx-note">Este módulo administra archivos y permisos. La compra y la instalación de plugins son operaciones distintas; subir aquí un ZIP no instala ni ejecuta su código.</p></div></section></div>
<section class="nx-panel" style="margin-top:24px"><div class="nx-panel-head"><h2><?= $total ?> recursos y versiones</h2></div><form method="get" class="nx-panel-body nx-actions"><label>Buscar<input name="q" maxlength="100" value="<?= $e($q) ?>" placeholder="Título o nombre de archivo"></label><label>Colección<select name="folder"><option value="">Todas</option><?php foreach ($folders as $collection): ?><option <?= $folder===$collection['folder']?'selected':'' ?>><?= $e($collection['folder']) ?></option><?php endforeach ?></select></label><button class="nx-btn">Buscar</button></form><div class="nx-panel-body nx-stack">
<?php foreach ($files as $file): ?><details class="nx-form-field" data-download-resource="<?= (int)$file['id'] ?>"><summary><strong data-nx-content><?= $e($file['title']) ?></strong> · v<?= $e($file['version_label']) ?> · <?= $e($file['status']) ?> · <?= $e($file['folder']) ?></summary><p data-nx-content><?= $e($file['description']??'') ?></p><p class="nx-small"><?= $e($file['original_name']) ?> · <?= $file['file_bytes']!==null?number_format((int)$file['file_bytes']/1024,1,',','.').' KB':'Tamaño pendiente' ?> · <?= $file['present']?'Archivo disponible':'Archivo físico no disponible' ?></p><p class="nx-code nx-small" style="overflow-wrap:anywhere">SHA-256: <?= $e($file['sha256']??'Se calculará en su primera entrega autorizada') ?></p><div class="nx-actions"><a class="nx-btn small" href="?edit=<?= (int)$file['id'] ?>">Editar permisos</a><a class="nx-btn small" href="?admin_download=<?= (int)$file['id'] ?>">Descarga administrativa</a><?php if (\App\Core\FrontendEngine::isModuleActive('s3-connector')): ?><a class="nx-btn small" href="<?= $e(\App\Core\AdminPath::url('/admin/s3-connector')) ?>?library=downloads&amp;reference=<?= (int)$file['id'] ?>">Copiar a S3</a><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="file_id" value="<?= (int)$file['id'] ?>"><button class="nx-btn small" name="action" value="<?= $file['status']==='active'?'archive':'restore' ?>"><?= $file['status']==='active'?'Archivar':'Reactivar' ?></button></form></div>
<?php if ($file['status']==='active'&&$file['present']): ?><form method="post" class="nx-stack nx-form-field" style="margin-top:20px"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="link"><input type="hidden" name="file_id" value="<?= (int)$file['id'] ?>"><div class="nx-operation-grid"><label>Vigencia (horas)<input name="ttl_hours" type="number" min="1" max="720" value="24" required></label><label>Máximo de accesos (0 = sin límite)<input name="max_uses" type="number" min="0" max="1000000" value="0" required></label></div><label>Reservar enlace a una cuenta<select name="bound_user"><option value="0">Aplicar permisos del recurso</option><?php foreach ($users as $user): ?><option value="<?= (int)$user['id'] ?>"><?= $e($user['username']) ?></option><?php endforeach ?></select></label><button class="nx-btn">Generar enlace revocable</button></form><?php endif ?>
<?php foreach ($file['links'] as $link): ?><div class="nx-form-field" style="margin-top:14px"><p class="nx-small"><?= $link['revoked_at']?'Revocado':((int)$link['expires_at']<=time()?'Vencido':'Con vigencia') ?> · <?= (int)$link['uses'] ?> / <?= (int)$link['max_uses']?:'sin límite' ?> accesos · <?= $link['bound_user']?'Cuenta #'.(int)$link['bound_user']:'Según permisos del recurso' ?></p><input readonly value="<?= $e(rtrim(\App\Core\Environment::get('APP_URL'),'/').\App\Core\DownloadLibrary::url($link)) ?>" onclick="this.select()" aria-label="Enlace controlado del recurso"><label>Insertar en una página<input readonly aria-label="Código para insertar este recurso" value="<?= $e('[goldensite_download id="'.$file['id'].'" link="'.$link['id'].'"]') ?>" onclick="this.select()"></label><?php if (!$link['revoked_at']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="link_id" value="<?= $e($link['id']) ?>"><button class="nx-btn small danger">Revocar enlace</button></form><?php endif ?></div><?php endforeach ?>
<?php if ((int)$file['allow_legacy_links']&&$file['status']==='active'&&$file['access_mode']==='public_link'): ?><details style="margin-top:16px"><summary>Compatibilidad: enlace temporal antiguo de una hora</summary><p class="nx-note">Este formato no tiene revocación individual. Prefiere los enlaces controlados nuevos.</p><input readonly value="<?= $e(\App\Core\PaywallEngine::generateSignedDownloadUrl((int)$file['id'])) ?>" onclick="this.select()"><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="file_id" value="<?= (int)$file['id'] ?>"><button class="nx-btn small" name="action" value="disable_legacy">Retirar enlaces antiguos de este recurso</button></form></details><?php endif ?>
<details style="margin-top:18px"><summary>Eliminar definitivamente el archivo físico</summary><form method="post" class="nx-stack"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="purge"><input type="hidden" name="file_id" value="<?= (int)$file['id'] ?>"><label>Contraseña actual<input type="password" name="current_password" required maxlength="72" autocomplete="current-password"></label><label><input type="checkbox" name="confirm_delete" value="1" required> Confirmo la eliminación del archivo y revocación de sus enlaces.</label><button class="nx-btn danger">Eliminar archivo físico</button></form></details></details><?php endforeach ?>
<?php if (!$files): ?><p class="nx-note">No hay recursos para estos filtros.</p><?php endif ?><div class="nx-actions"><?php if ($page>1): ?><a href="?q=<?= rawurlencode($q) ?>&amp;folder=<?= rawurlencode($folder) ?>&amp;page=<?= $page-1 ?>">Anterior</a><?php endif ?><?php if ($page<$pages): ?><a href="?q=<?= rawurlencode($q) ?>&amp;folder=<?= rawurlencode($folder) ?>&amp;page=<?= $page+1 ?>">Siguiente</a><?php endif ?></div></div></section>
<section class="nx-panel" style="margin-top:24px"><div class="nx-panel-head"><h2>Últimas 30 autorizaciones de entrega</h2></div><div class="nx-table-wrap"><table class="nx-table"><thead><tr><th>Recurso</th><th>Cuenta</th><th>Resultado</th><th>Fecha</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td data-nx-content><?= $e($event['title']??'Recurso retirado') ?></td><td><?= $event['user_id']?'#'.(int)$event['user_id']:'Enlace sin cuenta' ?></td><td><?= $e($event['result']) ?></td><td><?= $e($event['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
